internal static class AirSelfControl {
 static void Need(bool c,string s){if(!c)throw new Exception(s);}
 static void Run(bool validRecipe,bool cancel=false,bool omitFootprint=false,bool lanes=false){var em=new EntityManager();int next=20;em.LogicalAllocatorAdmitted=true;em.AllocateLogicalIdentity=()=>new Entity{Index=next++,Version=1};var ge=new Entity{Index=1,Version=1};var be=new Entity{Index=2,Version=1};var template=new Entity{Index=3,Version=1};em.ImportEntity(ge);em.ImportEntity(be);em.ImportEntity(template);var grid=new GridConfig{Width=16,Height=16,CellSize=1};em.AddComponentData(ge,grid);var walk=em.AddBuffer<GridWalkable>(ge);for(int i=0;i<256;i++)walk.Add(new GridWalkable{Value=1});var blocked=new NativeBitArray(256,Allocator.Temp);var occupied=new NativeBitArray(256,Allocator.Temp);em.AddComponentData(ge,new DynamicBlockerComponent{GridSize=256,Blocked=blocked});em.AddComponentData(ge,new DynamicOccupancyComponent{GridSize=256,Occupied=occupied});em.AddComponentData(template,new Prefab());em.AddComponentData(template,new UnitGrid());if(!omitFootprint)em.AddComponentData(template,new UnitFootprint{Size=new int2(1,1)});em.AddComponentData(template,LocalTransform.FromPosition(float3.zero));em.AddComponentData(template,new UnitAirMovement());em.AddComponentData(template,new UnitAirComponent());RuntimeActorBirthContext.BindNoNativeBirthRecordProfile(em,true,true,new[]{ge,be,template},e=>false);
 var prefab=new SourceUnitPrefab("Unit_Veh_Helicopter_Attack_Small",template);var def=new RuntimeDefinition{DisplayName="Building_Helipad",FootprintCells=new Vector2Int(2,2),ProductionSlots=new List<RuntimeDefinition.ProductionSlotDefinition>()};if(validRecipe)def.ProductionSlots.Add(new RuntimeDefinition.ProductionSlotDefinition{SpawnUnitPrefab=prefab,SpawnUnitSourceKey=new FixedString64Bytes("unit_veh_helicopter_attack_small"),Quantity=1});var b=new RuntimeBuildingEntity{Id=17,HasOwnerFaction=true,OwnerFactionId=1,InitialProducerCollectionsKnown=true,OriginCell=new Vector2Int(4,4),Definition=def,Instance=new RuntimeInstance{transform=new RuntimeTransform{position=new Vector3(5.5f,0,5.5f)}},ProductionSpawnLocalPositions=new[]{new Vector3(0,0,0)},ProducedUnitSlots=new Entity[1],PendingProductions=new List<SourcePendingProduction>()};var buildings=new Dictionary<int,RuntimeBuildingEntity>{{17,b}};var world=new SourceProductionGroundWorld(em,ge,be,buildings,new Dictionary<int,PoseGraph>());world.ProducerRootFrames=new Dictionary<int,SourceProducerRootFrame>{{17,new SourceProducerRootFrame(new float3(5.5f,0,5.5f),quaternion.identity,1)}};var points=em.AddBuffer<BuildingFactionProductionSpawnPointReadModel>(be);points.Add(new BuildingFactionProductionSpawnPointReadModel{FactionId=1,BuildingId=new FixedString128Bytes("building_helipad"),BuildingRuntimeId=17,SlotIndex=0,Cell=new int2(5,5),WorldPosition=new float3(5.5f,0,5.5f)});
 var prod=new BuildingProductionQueueCompositionSystemHelper();var owner=new SourceProductionDeliveryOwner(world,prod,world.SpawnContext,new Dictionary<int,SourceProductionDeliveryRecipe[]>(),1,1);var frames=new[]{new PoseFrame{Parent=-1,Name="fixture",Position=float3.zero,Scale=new float3(1),Rotation=quaternion.identity}};Func<PoseGraph> pose=()=>new PoseGraph(frames,new MeshBounds[0],new int[0],true,true,true,true);var desc=new SourceTransportTemplateData(prefab,pose,new MeshBounds[0],new bool[0],true,-1);var templates=new Dictionary<SourceUnitPrefab,SourceTransportTemplateData>{{prefab,desc}};var delivery=new SourceHelicopterDelivery(owner,templates,true,false,default,default,(SourceProductionGroundWorld w,int2 p,ref NativeBitArray r)=>{});var pending=new SourcePendingProduction{ProductionIndex=0,Prefab=prefab,ReadyAt=0,RemainingQuantity=1,ReservedProductionSlotIndex=-1,TransportPrefab=prefab,TransportMode=BuildingProductionQueueCompositionSystemHelper.ProductionTransportMode.AirSelf,TransportArrivalSeconds=1,TransportHoldForNextReadySeconds=1,TransportMaxConcurrent=1};b.PendingProductions.Add(pending);var unavailable=new SourceHelicopterDelivery(owner,new Dictionary<SourceUnitPrefab,SourceTransportTemplateData>(),true,false,default,default,(SourceProductionGroundWorld w,int2 p,ref NativeBitArray r)=>{});bool rejected=false;try{unavailable.TryEnsure(b,pending,0);}catch(NotSupportedException){rejected=true;}Need(rejected,"unknown template rejected");var missing=SourceUnitPrefab.FromAssetIdentity("fixture_missing","Assets/fixture.prefab",new string('0',32),1);templates.Add(missing,new SourceTransportTemplateData(missing,pose,new MeshBounds[0],new bool[0],true,-1));var missingPending=new SourcePendingProduction{Prefab=missing,TransportPrefab=missing,TransportMode=BuildingProductionQueueCompositionSystemHelper.ProductionTransportMode.AirSelf,TransportMaxConcurrent=1};rejected=false;try{delivery.TryEnsure(b,missingPending,0);}catch(NotSupportedException){rejected=true;}Need(rejected,"missing ECS prefab template rejected");Need(delivery.TryEnsure(b,pending,0),"admit self arrival");if(lanes){var second=new RuntimeBuildingEntity{Id=18,HasOwnerFaction=true,OwnerFactionId=1,InitialProducerCollectionsKnown=true,OriginCell=new Vector2Int(8,8),Definition=new RuntimeDefinition{DisplayName="Building_Helipad",FootprintCells=new Vector2Int(2,2),ProductionSlots=new List<RuntimeDefinition.ProductionSlotDefinition>()},Instance=new RuntimeInstance{transform=new RuntimeTransform{position=new Vector3(8.5f,0,8.5f)}},ProductionSpawnLocalPositions=new[]{new Vector3(0,0,0)},ProducedUnitSlots=new Entity[1],PendingProductions=new List<SourcePendingProduction>()};buildings.Add(18,second);world.ProducerRootFrames=new Dictionary<int,SourceProducerRootFrame>{{17,new SourceProducerRootFrame(new float3(5.5f,0,5.5f),quaternion.identity,1)},{18,new SourceProducerRootFrame(new float3(8.5f,0,8.5f),quaternion.identity,1)}};var p2=new SourcePendingProduction{ProductionIndex=0,Prefab=prefab,ReadyAt=0,RemainingQuantity=1,ReservedProductionSlotIndex=-1,TransportPrefab=prefab,TransportMode=BuildingProductionQueueCompositionSystemHelper.ProductionTransportMode.AirSelf,TransportArrivalSeconds=1,TransportHoldForNextReadySeconds=1,TransportMaxConcurrent=1};second.PendingProductions.Add(p2);Need(!delivery.TryEnsure(second,p2,0),"same prefab full lane rejected");var other=new SourceUnitPrefab("Unit_Veh_Helicopter_Attack",template);templates.Add(other,new SourceTransportTemplateData(other,pose,new MeshBounds[0],new bool[0],true,-1));p2.Prefab=other;p2.TransportPrefab=other;Need(delivery.TryEnsure(second,p2,0),"different prefab independent lane");delivery.Advance(1,1);delivery.Advance(2.5f,1f);Need(!delivery.AnyActive&&second.PendingProductions.Count==1,"failed spawn releases lane but retains pending");p2.Prefab=prefab;p2.TransportPrefab=prefab;Need(delivery.TryEnsure(second,p2,3),"lane reusable after success/failure cleanup");return;}delivery.Advance(1,1);Need(delivery.AnyActive&&b.PendingProductions.Count==1,"arrival retains pending");delivery.Advance(1.75f,.75f);Need(delivery.AnyActive&&b.PendingProductions.Count==1,"half descent no delivery");delivery.Advance(2.499f,.749f);Need(delivery.AnyActive&&b.PendingProductions.Count==1,"before 1.5 seconds no delivery");if(cancel){b.PendingProductions.Clear();delivery.Advance(2.5f,.001f);Need(delivery.AnyActive,"cancellation initiates departure");delivery.Advance(3.5f,1);Need(!delivery.AnyActive,"AirSelf original departure duration");return;}delivery.Advance(2.5f,.001f);Need(!delivery.AnyActive,"completed or failed self arrival retires visual");if(validRecipe){Need(b.PendingProductions.Count==0,"successful spawn releases pending");Need(owner.DeliveredMembers==1,"successful spawn recorded");}else{Need(b.PendingProductions.Count==1,"failed spawn preserves pending");Need(owner.DeliveredMembers==0,"failed spawn not delivered");}}
 static void Main(){try{PoseMath.AdmitInstalledMono();Run(true);Run(false);Run(true,true);Run(true,false,true);Run(true,false,false,true);Console.WriteLine("[AirSelfLifecycleControls] Passed missing-template rejection, arrival/descent boundary, success/pending release, failed spawn retention cancelled departure, native 1x1 fallback and prefab-scoped lane reuse; synthetic world only");}catch(Exception e){Console.Error.WriteLine(e);Environment.Exit(1);}}
}
